class Solution {
public:
    long long minimumTime(std::vector<int>& power) {
        int n = power.size();
        int total_states = 1 << n;
        std::vector<long long> dp(total_states, -1);
        dp[0] = 0;

        for (int mask = 0; mask < total_states; mask++) {
            if (dp[mask] == -1) continue;
            int gain = __builtin_popcount(mask) + 1;
            for (int i = 0; i < n; i++) {
                if (!(mask & (1 << i))) {
                    int nxt = mask | (1 << i);
                    long long days = (power[i] + gain - 1LL) / gain;
                    if (dp[nxt] == -1 || dp[mask] + days < dp[nxt]) {
                        dp[nxt] = dp[mask] + days;
                    }
                }
            }
        }
        return dp[total_states - 1];
    }
};

class Solution {
    public long minimumTime(int[] power) {
        int n = power.length;
        int totalStates = 1 << n;
        long[] dp = new long[totalStates];
        java.util.Arrays.fill(dp, -1);
        dp[0] = 0;

        for (int mask = 0; mask < totalStates; mask++) {
            if (dp[mask] == -1) continue;
            int gain = Integer.bitCount(mask) + 1;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) == 0) {
                    int nxt = mask | (1 << i);
                    long days = ((long) power[i] + gain - 1) / gain;
                    if (dp[nxt] == -1 || dp[mask] + days < dp[nxt]) {
                        dp[nxt] = dp[mask] + days;
                    }
                }
            }
        }
        return dp[totalStates - 1];
    }
}

var minimumTime = function(power) {
    const n = power.length;
    const totalStates = 1 << n;
    const dp = new Array(totalStates).fill(Infinity);
    dp[0] = 0;

    function popcount(x) {
        let cnt = 0;
        while (x > 0) {
            cnt += (x & 1);
            x >>= 1;
        }
        return cnt;
    }

    for (let mask = 0; mask < totalStates; mask++) {
        if (dp[mask] === Infinity) continue;
        const gain = popcount(mask) + 1;
        for (let i = 0; i < n; i++) {
            if ((mask & (1 << i)) === 0) {
                const nxt = mask | (1 << i);
                const days = Math.ceil(power[i] / gain);
                if (dp[mask] + days < dp[nxt]) {
                    dp[nxt] = dp[mask] + days;
                }
            }
        }
    }
    return dp[totalStates - 1];
};
